import java.util.*;

public class Main {
    int reverse(int x) {
        boolean negative = x < 0;
        String digits = new StringBuilder(String.valueOf(Math.abs((long) x))).reverse().toString();
        long reversedX = Long.parseLong(digits);          // parse back into a number, as a wider type first
        if (negative) {
            reversedX = -reversedX;                          // reapply the sign
        }
        if (reversedX < Integer.MIN_VALUE || reversedX > Integer.MAX_VALUE) {
            return 0;                                          // outside the signed 32 bit integer range
        }
        return (int) reversedX;
    }

    public static void main(String[] args) {
        int x = 123;
        Main solution = new Main();
        System.out.println(solution.reverse(x));
    }
}

