import java.util.*;

public class Main {
    int reverse(int x) {
        int sign = x < 0 ? -1 : 1;
        x = Math.abs(x);
        int result = 0;
        while (x != 0) {
            int digit = x % 10;                               // peel off the last digit
            x /= 10;                                            // drop that digit from the remaining number
            if (result > (Integer.MAX_VALUE - digit) / 10) {
                return 0;                                         // this digit would push the result out of range
            }
            result = result * 10 + digit;                       // shift the result left and add the new digit
        }
        return sign * result;
    }

    public static void main(String[] args) {
        int x = 123;
        Main solution = new Main();
        System.out.println(solution.reverse(x));
    }
}

